import pyomo.environ as pyo

DATA = {
    "packages": ["banana_haters", "combo"],
    "resources": ["apples", "bananas", "grapes"],
    # stock availability per resource
    "availability": {"apples": 10, "bananas": 20, "grapes": 80},
    # usage of each resource per package
    "usage": {
        "banana_haters": {"apples": 6, "bananas": 0, "grapes": 30},
        "combo":         {"apples": 5, "bananas": 6, "grapes": 20},
    },
    # profit per package
    "profit": {"banana_haters": 6, "combo": 7},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PACKAGES = pyo.Set(initialize=d["packages"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    # Decision: how many of each package to prepare
    model.packages = pyo.Var(
        model.PACKAGES,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.packages[p] for p in m.PACKAGES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource availability constraints
    def resource_rule(m, r):
        return sum(
            d["usage"][p][r] * m.packages[p] for p in m.PACKAGES
        ) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.RESOURCES, rule=resource_rule)

    return model


