import pyomo.environ as pyo

DATA = {
    "packages": ["banana_haters", "combo"],
    "resources": ["apples", "bananas", "grapes"],
    "profit": {
        "banana_haters": 6,
        "combo": 7,
    },
    "usage": {
        # resource -> {package: amount consumed per package}
        "apples":  {"banana_haters": 6, "combo": 5},
        "bananas": {"banana_haters": 0, "combo": 6},
        "grapes":  {"banana_haters": 30, "combo": 20},
    },
    "stock": {
        "apples": 10,
        "bananas": 20,
        "grapes": 80,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["packages"])
    model.R = pyo.Set(initialize=d["resources"])

    # Decision variables: integer number of each package to prepare (>=0)
    model.x = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    # Objective: maximize total profit
    model.obj = pyo.Objective(
        expr=sum(d["profit"][p] * model.x[p] for p in model.P),
        sense=pyo.maximize,
    )

    # Constraints: stock availability per resource (<= available stock)
    def stock_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["stock"][r]

    model.stock_limit = pyo.Constraint(model.R, rule=stock_rule)

    return model


